1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	// replicateInput 是 replicate 子命令从标准输入读取的 JSON。
15	type replicateInput struct {
16		CurrentTerm    int                      `json:"currentTerm"`
17		CommittedIndex int                      `json:"committedIndex"`
18		Log            []mevwatch.LogEntry      `json:"log"`
19		ApplyKV        bool                     `json:"applyKV"`
20		Requests       []mevwatch.AppendRequest `json:"requests"`
21	}
22	
23	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
24	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
25	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
26	func runReplicate() int {
27		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
28	}
29	
30	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
31		data, err := io.ReadAll(stdin)
32		if err != nil {
33			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
34			return 1
35		}
36		var syntaxCheck interface{}
37		if err := json.Unmarshal(data, &syntaxCheck); err != nil {
38			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
39			return 1
40		}
41		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
42		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
43		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
44		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
45		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
46		// 前一份数组，因此重复键的每一次出现都必须单独检查。
47		if path := nullNumericFieldPath(data); path != "" {
48			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
49			return 1
50		}
51		var input replicateInput
52		if err := json.Unmarshal(data, &input); err != nil {
53			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
54			return 1
55		}
56		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
57			CurrentTerm:    input.CurrentTerm,
58			CommittedIndex: input.CommittedIndex,
59			Log:            input.Log,
60		}, input.Requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
61		if err != nil {
62			fmt.Fprintf(stderr, "replicate: %v\n", err)
63			return 1
64		}
65		encoded, err := json.MarshalIndent(output, "", "  ")
66		if err != nil {
67			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
68			return 1
69		}
70		fmt.Fprintln(stdout, string(encoded))
71		return 0
72	}
