74	// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
75	// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
76	// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
77	// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
78	// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
79	type objectSchema struct {
80		numerics []string
81		arrays   []arrayField
82	}
83	
84	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
85	// 所在层次的 schema。
86	type arrayField struct {
87		name string
88		elem *objectSchema
89	}
90	
91	var (
92		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
93		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
94		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
95		requestObjectSchema = &objectSchema{
96			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
97			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
98		}
99		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
100		rootObjectSchema = &objectSchema{
101			numerics: []string{"currentTerm", "committedIndex"},
102			arrays: []arrayField{
103				{name: "log", elem: entryObjectSchema},
104				{name: "requests", elem: requestObjectSchema},
105			},
106		}
107	)
108	
109	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
110	func (s *objectSchema) numericName(key string) (string, bool) {
111		for _, name := range s.numerics {
112			if strings.EqualFold(key, name) {
113				return name, true
114			}
115		}
116		return "", false
117	}
118	
119	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
120	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
121		for _, field := range s.arrays {
122			if strings.EqualFold(key, field.name) {
123				return field, true
124			}
125		}
126		return arrayField{}, false
127	}
128	
129	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
130	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
131	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
132	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
133	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
134	// requests[1].leaderCommit。
135	//
136	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
137	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
138	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
139	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
140	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
141	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
142	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
143	func nullNumericFieldPath(data []byte) string {
144		dec := json.NewDecoder(bytes.NewReader(data))
145	
146		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
