1	// 已提交命令的键值应用：把日志命令解释为 set/delete/incr 键值操作，在本次调用内
2	// 从空键值表开始，随提交位置推进按日志索引顺序应用。本文件只做纯逻辑处理。
3	package mevwatch
4	
5	import (
6		"strconv"
7		"strings"
8		"unicode"
9	)
10	
11	// 键值命令格式错误的原因（稳定标识符，帮助文档中有说明）。
12	const (
13		ApplyReasonUnknownCommand   = `invalid command: expected "set <key>=<value>" or "delete <key>"`
14		ApplyReasonEmptyKey         = "invalid command: key is empty"
15		ApplyReasonKeyHasWhitespace = "invalid command: key contains whitespace"
16		ApplyReasonKeyHasEquals     = "invalid command: key contains '='"
17		ApplyReasonSetMissingEquals = "invalid command: set requires '=' between key and value"
18		// incr 特有的三类失败：增量本身非法、当前值不是整数、相加溢出。
19		ApplyReasonIncrMissingEquals = "invalid command: incr requires '=' between key and delta"
20		ApplyReasonIncrBadDelta      = "invalid command: incr delta is not a signed 64-bit decimal integer"
21		ApplyReasonIncrBadCurrent    = "invalid command: current value is not a signed 64-bit decimal integer"
22		ApplyReasonIncrOverflow      = "invalid command: incr result exceeds signed 64-bit integer range"
23	)
24	
25	// ApplyError 描述已提交命令中第一个格式错误：出错条目的日志索引与具体原因。
26	type ApplyError struct {
27		Index  int    `json:"index"`
28		Reason string `json:"reason"`
29	}
30	
31	// kvOperation 是一条解析成功的键值命令。各动作共有的格式规则（等号分隔、键
32	// 校验）由 parseKVCommand 统一保证；各动作自己的参数含义与失败原因由各自的
33	// apply 方法保留，执行方不再区分动作种类。
34	type kvOperation struct {
35		isDelete bool
36		isIncr   bool
37		key      string
38		value    string // 仅 set 使用；按原文保留，允许为空
39		delta    int64  // 仅 incr 使用；解析时已校验为有符号 64 位整数
40	}
41	
42	// parseKVCommand 把一条命令解释为键值操作，失败时返回具体原因。
43	// 命令区分大小写，命令名后必须恰好有一个普通空格；键不能为空、不能含空白
44	// 或等号；set 与 incr 都以键后的第一个等号分隔参数：set 的值按原文保留
45	// （可为空、含空格、中文及额外等号），incr 的增量必须是有符号 64 位十进制
46	// 整数（允许负号与前导零，其余形式一律非法）。命令两端不做任何空白裁剪。
47	func parseKVCommand(command string) (kvOperation, string) {
48		if rest, ok := strings.CutPrefix(command, "set "); ok {
49			key, value, reason := splitKVPair(rest, ApplyReasonSetMissingEquals)
50			if reason != "" {
51				return kvOperation{}, reason
52			}
53			return kvOperation{key: key, value: value}, ""
54		}
55		if rest, ok := strings.CutPrefix(command, "delete "); ok {
56			if reason := validateKVKey(rest); reason != "" {
57				return kvOperation{}, reason
58			}
59			return kvOperation{isDelete: true, key: rest}, ""
60		}
61		if rest, ok := strings.CutPrefix(command, "incr "); ok {
62			key, deltaText, reason := splitKVPair(rest, ApplyReasonIncrMissingEquals)
63			if reason != "" {
64				return kvOperation{}, reason
65			}
66			delta, ok := parseKVInt(deltaText)
67			if !ok {
68				return kvOperation{}, ApplyReasonIncrBadDelta
69			}
70			return kvOperation{isIncr: true, key: key, delta: delta}, ""
71		}
72		return kvOperation{}, ApplyReasonUnknownCommand
73	}
74	
75	// splitKVPair 按键后的第一个等号把命令参数分成键与值，并校验键。缺少等号时
76	// 返回调用方给定的原因：写入与累加分别说明缺少值的分隔符或增量的分隔符，
77	// 等号分隔与键校验这套共有规则只在此维护一份。
78	func splitKVPair(rest, missingEquals string) (key, value, reason string) {
79		eq := strings.IndexByte(rest, '=')
80		if eq < 0 {
81			return "", "", missingEquals
82		}
83		key, value = rest[:eq], rest[eq+1:]
84		if reason := validateKVKey(key); reason != "" {
85			return "", "", reason
86		}
87		return key, value, ""
88	}
89	
90	// validateKVKey 校验键：不能为空、不能含空白或等号。
91	func validateKVKey(key string) string {
92		if key == "" {
93			return ApplyReasonEmptyKey
94		}
95		for _, r := range key {
96			if unicode.IsSpace(r) {
97				return ApplyReasonKeyHasWhitespace
98			}
99			if r == '=' {
100				return ApplyReasonKeyHasEquals
101			}
102		}
103		return ""
104	}
105	
106	// parseKVInt 把字符串按有符号 64 位十进制整数解析：允许负号与前导零，
107	// 不接受正号、空白、小数、指数形式或非 ASCII 数字，空字符串也不是整数；
108	// 超出 int64 范围同样失败。先逐字节校验形状，再交给 strconv 判定范围。
109	func parseKVInt(s string) (int64, bool) {
110		digits := s
111		if strings.HasPrefix(digits, "-") {
112			digits = digits[1:]
113		}
114		if digits == "" {
115			return 0, false
116		}
117		for i := 0; i < len(digits); i++ {
118			if digits[i] < '0' || digits[i] > '9' {
119				return 0, false
120			}
121		}
122		value, err := strconv.ParseInt(s, 10, 64)
123		if err != nil {
124			return 0, false
125		}
126		return value, true
127	}
128	
129	// addKVInt 计算两个有符号 64 位整数之和，结果超出 int64 范围时 ok 为 false。
130	func addKVInt(a, b int64) (sum int64, ok bool) {
131		sum = a + b
132		// Go 的有符号溢出按二进制补码回绕：b 为正而和反而变小，或 b 为负而和
133		// 反而变大，即越界。
134		if (b > 0 && sum < a) || (b < 0 && sum > a) {
135			return 0, false
136		}
137		return sum, true
138	}
139	
140	// kvApplier 在本次调用内从空键值表开始，按日志索引顺序应用已提交命令。
141	// 一旦遇到格式错误，应用状态停住：已应用索引不再前进，错误保留到调用结束。
142	type kvApplier struct {
143		kv           map[string]string
144		appliedIndex int         // 已应用的最高日志索引，0 表示尚未应用任何条目
145		err          *ApplyError // 非空后应用状态停住
146	}
147	
148	func newKVApplier() *kvApplier {
149		return &kvApplier{kv: map[string]string{}}
150	}
151	
152	// applyUpTo 应用 (appliedIndex, committedIndex] 区间内尚未应用的已提交条目。
153	// 只前进不后退：空条目心跳、重复复制、提交位置不变时不会重复应用（incr 也
154	// 不会因此重复累加）；已出错时不再应用任何条目。未提交的条目不在此触及，
155	// 其格式错误不会提前暴露。
156	func (a *kvApplier) applyUpTo(log []LogEntry, committedIndex int) {
157		if a.err != nil {
158			return
159		}
160		for a.appliedIndex < committedIndex {
161			next := a.appliedIndex + 1
162			op, reason := parseKVCommand(log[next-1].Command)
163			if reason == "" {
164				reason = op.apply(a.kv)
165			}
166			if reason != "" {
167				// 保留此前已成功应用的结果，已应用索引停在出错位置的前一条；
168				// 本条命令不改变键值表。
169				a.err = &ApplyError{Index: next, Reason: reason}
170				return
171			}
172			a.appliedIndex = next
173		}
174	}
175	
176	// apply 把解析成功的操作作用到键值表，成功时返回空原因。各动作保留自己的
177	// 参数含义与失败原因：set 按原文写值，delete 删除（键不存在同样算成功），
178	// incr 按此前已生效的值累加。失败时键值表保持不变。
179	func (op kvOperation) apply(kv map[string]string) string {
180		switch {
181		case op.isDelete:
182			delete(kv, op.key)
183			return ""
184		case op.isIncr:
185			return op.applyIncr(kv)
186		default:
187			kv[op.key] = op.value
188			return ""
189		}
190	}
191	
192	// applyIncr 计算一次增量后的新值并写回：键不存在时当前值按 0 处理（并因此
193	// 创建该键）；当前值必须是有符号 64 位十进制整数，相加结果也不得超出该范围。
194	// 成功时写回不带前导零的规范十进制形式（零统一为 "0"），增量为 0 同样写回
195	// 规范形式；失败时返回具体原因，键值表保持不变。
196	func (op kvOperation) applyIncr(kv map[string]string) string {
197		current := int64(0)
198		if existing, ok := kv[op.key]; ok {
199			value, valid := parseKVInt(existing)
200			if !valid {
201				return ApplyReasonIncrBadCurrent
202			}
203			current = value
204		}
205		sum, ok := addKVInt(current, op.delta)
206		if !ok {
207			return ApplyReasonIncrOverflow
208		}
209		kv[op.key] = strconv.FormatInt(sum, 10)
210		return ""
211	}
